frappe.listview_settings["Sales Order"].get_indicator = function(doc) {
    if (doc.workflow_state) {
        let color = "blue";
        if (doc.workflow_state === "Order Completed" || doc.workflow_state === "Completed") color = "green";
        if (doc.workflow_state === "Rejected" || doc.workflow_state === "Credit Hold") color = "red";
        if (doc.workflow_state === "Draft") color = "gray";
        if (doc.workflow_state === "Invoiced" || doc.workflow_state === "Dispatched") color = "orange";
        return [__(doc.workflow_state), color, "workflow_state,=," + doc.workflow_state];
    }
    return [__(doc.status), "gray", "status,=," + doc.status];
};
